public class InnerDestinationEndpointStandardDestinationEndpointConfigurationFactory(Action<Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration>
{

    internal InnerDestinationEndpointStandardDestinationEndpointNetworkingConfigurationFactory DestinationNetworkingConfigurationFactory { get; set; }

    internal InnerDestinationEndpointStandardDestinationEndpointProtocolConfigurationFactory ProtocolConfigurationFactory { get; set; }

    protected override Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration Create()
    {
        var standardDestinationEndpointConfigurationResult = CreateStandardDestinationEndpointConfiguration();
        factoryAction?.Invoke(standardDestinationEndpointConfigurationResult);

        return standardDestinationEndpointConfigurationResult;
    }

    private Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration CreateStandardDestinationEndpointConfiguration()
    {
        var standardDestinationEndpointConfigurationResult = new Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration();

        return standardDestinationEndpointConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.DestinationEndpointTypes.StandardDestinationEndpointConfiguration result)
    {
        base.CreateChildren(result);

        result.DestinationNetworkingConfiguration ??= DestinationNetworkingConfigurationFactory?.Build();
        result.ProtocolConfiguration ??= ProtocolConfigurationFactory?.Build();
    }

} // End Of Class

